import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef,
} from '@angular/core';
import { SentinelExtendedSubscription } from '../../pages/vpn-page/vpn-page.definitions';
import { ControlsOf, FormBuilder, FormGroup } from '@ngneat/reactive-forms';
import { map, Observable, of } from 'rxjs';
import { SentinelService } from '@core/services';
import { PricePipe } from '@shared/pipes/price';
import { VpnPageService } from '../../pages';
import { catchError, debounceTime, switchMap, tap } from 'rxjs/operators';
import { ONE_SECOND } from '@shared/utils/date';
import {UntilDestroy, untilDestroyed} from '@ngneat/until-destroy';
import { Validators } from '@angular/forms';
import { priceFromString } from '@shared/utils/price';
import { Coin } from 'decentr-js';
interface SubscribeForm {
  deposit: number;
}
@UntilDestroy()
@Component({
  selector: 'app-plan-subscribe',
  templateUrl: './plan-subscribe.component.html',
  styleUrls: ['./plan-subscribe.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PlanSubscribeComponent implements OnInit {

  @Input() public maxDeposit: number;

  @Input() public price: number;

  @Input() public plan: any;

  @Input() public subscribed: boolean;

  @Output() public subscribe: EventEmitter<any> = new EventEmitter();

  public form!: FormGroup<ControlsOf<SubscribeForm>>;

  public depositCapacity$!: Observable<number>;

  public fee: number;

  public canSubscribe: boolean;

  public canSubscribeLoading: boolean;

  public insufficientFunds: boolean;

  constructor(
    private changeDetectorRef: ChangeDetectorRef,
    private formBuilder: FormBuilder,
    private pricePipe: PricePipe,
    private vpnPageService: VpnPageService,
  ) {
  }


  public ngOnInit(): void {
    this.form = this.createForm();

    this.depositCapacity$ = this.form.get('deposit').value$.pipe(
      map((selectedPrice) => selectedPrice / +this.price),
    );

    this.form.value$.pipe(
      tap(() => {
        this.fee = 0;
        this.canSubscribe = false;
        this.canSubscribeLoading = false;
        this.insufficientFunds = false;
      }),
      debounceTime(ONE_SECOND ),
      switchMap((formValue) => {
        const deposit = formValue.deposit;

        return of(0)
      }),
      untilDestroyed(this),
    ).subscribe((fee) => {
      const deposit = this.form.get('deposit').value;

      this.canSubscribeLoading = false;
      this.fee = fee;
      this.canSubscribe = this.maxDeposit - this.fee >= deposit;
      this.insufficientFunds = this.maxDeposit < deposit;

      this.changeDetectorRef.markForCheck();
    });

    this.vpnPageService.subscriptionCreated().pipe(
      untilDestroyed(this),
    ).subscribe(() => {
      this.form.get('deposit').setValue(+this.price);
    });
  }
  public async connectWallet() {
    window.open('https://swapfortest.mainnet.decentr.xyz/');
  }
  private buildCoin(deposit: number): Coin {
    return {
      denom: 'dec',
      amount: deposit.toString(),
    };
  }

  public createForm(): FormGroup<ControlsOf<SubscribeForm>> {
    return this.formBuilder.group({
      deposit: [
        0,
        [
          Validators.required,
        ],
      ],
    });
  }

  public subscribeToNode(): void {
    const { deposit } = this.form.getRawValue();
    this.depositCapacity$.pipe(
      map(duration => ({
        plan_id: this.plan.plan_id,
        duration: duration,
        sub_id: this.plan.subscription_id,
        uuid: this.plan.uuid,
        amt: this.plan.plan_dvpn_price,
        denom: this.plan.plan_denom,
      })),
    ).subscribe(res => this.subscribe.emit({
      data: res,
      deposit: deposit,
    }));
  }

  public displayWith = (value: number): string => {
    return this.pricePipe.transform(priceFromString(value + 'DEC')[0]);
  };
}
