import { ChangeDetectionStrategy, Component, OnInit } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { isOpenedInTab } from '@shared/utils/browser';
import { svgTopup } from '@shared/svg-icons/topup';
import { SvgIconRegistry } from '@ngneat/svg-icon';
import { AiPageService } from './ai-page.service';
import { Message, SenderType } from './ai-page.definitions';
import { AthenaBalance, QueryItem } from 'decentr-js';
import {delay, filter, map, pairwise, retry} from 'rxjs/operators';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import {NavigationEnd, Router} from '@angular/router';
import {svgReload} from "@shared/svg-icons/reload";

@UntilDestroy()
@Component({
  selector: 'app-ai-page',
  templateUrl: './ai-page.component.html',
  styleUrls: ['./ai-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.Default,
  providers: [
    AiPageService,
  ],
})
export class AiPageComponent implements OnInit {

  public isOpenedInTab = isOpenedInTab();

  public balance$: BehaviorSubject<AthenaBalance> = new BehaviorSubject<AthenaBalance>(undefined);

  public messages$: BehaviorSubject<Message[]> = new BehaviorSubject<Message[]>([]);

  public isSending$: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);

  constructor(
    private aiPageService: AiPageService,
    private svgIconRegistry: SvgIconRegistry,
  ) { }

  ngOnInit(): void {
    this.svgIconRegistry.register([
      svgReload,
      svgTopup,
    ]);

    this.updateBalance();

    this.aiPageService.getQueries({
      userWallet: this.aiPageService.walletAddress,
      take: 10,
      skip: 0,
    }).subscribe(res => {
      this.messages$.next(this.convertToMessages(res.slice().reverse()));
    });
  }

  public topUpBalance(): void {
    this.aiPageService.topUpBalance();
  }

  public markAsPaid(id: string) {
    this.aiPageService.markAsPaid(id).subscribe(res => {
      if (res) {
        const currentMessages = this.messages$.getValue() || [];
        const messageIndex = currentMessages.findIndex(message => message.id === id && message.sender === SenderType.System);
        currentMessages[messageIndex].content = res;
        currentMessages[messageIndex].paid = true;
        this.messages$.next(currentMessages);
        this.updateBalance();
      }
    });
  }

  public ask(askBody: { content: string }): void {
    this.isSending$.next(true);

    const userMessage: Message = {
      content: askBody.content,
      timestamp: new Date(),
      sender: SenderType.User,
      paid: true,
    };

    // Update the subject with the new user message
    this.updateMessagesSubject(userMessage);

    this.aiPageService.ask({
      userWallet: this.aiPageService.walletAddress,
      question: askBody.content,
    }).pipe(
      retry(5),
    ).subscribe(res => {
      const systemMessage: Message = {
        content: res.message,
        timestamp: new Date(),
        sender: SenderType.System,
        paid: res.paid,
      };

      // Update the subject with the new system message
      this.updateMessagesSubject(systemMessage);
      this.updateBalance();
      this.isSending$.next(false);
    });
  }

  private updateMessagesSubject(message: Message): void {
    const currentMessages = this.messages$.getValue() || [];
    currentMessages.push(message);
    this.messages$.next(currentMessages);
  }

  public convertToMessages(queryItems: QueryItem[]): Message[] {
    const messages: Message[] = [];

    for (const queryItem of queryItems) {
      const { question, answer, createdAt, paid, id } = queryItem;

      const questionMessage: Message = {
        content: question,
        sender: SenderType.User,
        timestamp: new Date(createdAt),
        paid: true,
        id: id,
      };
      messages.push(questionMessage);

      const answerMessage: Message = {
        content: answer,
        sender: SenderType.System,
        timestamp: new Date(createdAt),
        paid: paid,
        id: id,
      };
      messages.push(answerMessage);
    }

    return messages;
  }

  public loadMore(skip) {
    const currentMessages = this.messages$.getValue() || [];
    this.aiPageService.getQueries({
      userWallet: this.aiPageService.walletAddress,
      take: 10,
      skip: skip,
    }).subscribe(res => {
      const newMessages = this.convertToMessages(res.slice().reverse());
      currentMessages.unshift(...newMessages);
      this.messages$.next(currentMessages);
    });
  }

  public updateBalance(): void {
    this.aiPageService.getBalance()
      .pipe(untilDestroyed(this))
      .subscribe((balance) => this.balance$.next(balance));
  }
}
