import { Injectable } from '@angular/core';
import { mergeMap, Observable, Subject, switchMap, tap } from 'rxjs';
import { BankService, DecentrService } from '@core/services';
import { AuthService } from '@core/auth';
import { map } from 'rxjs/operators';
import { AppRoute } from '../../../../../app-route';
import { PortalRoute } from '../../../../portal-route';
import { IS_AI_PARAM, RECEIVER_WALLET_PARAM } from '../../../assets/pages';
import { Router } from '@angular/router';
import {
  Ask,
  AskListQueryParams,
  createDecentrCoin,
  DecodedIndexedTx,
  QueryItem,
  SearchTxFilter,
  SearchTxQuery,
  AthenaBalance,
} from 'decentr-js';
import { Message } from './ai-page.definitions';
import { MICRO_PDV_DIVISOR } from '@shared/pipes/micro-value';
import {NotificationService} from "@shared/services/notification";
import {TranslatedError} from "@core/notifications";

@Injectable()
export class AiPageService {

  public messagesSubject: Subject<Message[]> = new Subject();

  constructor(
    private bankService: BankService,
    private authService: AuthService,
    private router: Router,
    private decentrService: DecentrService,
    private notificationService: NotificationService,
  ) { }

  public get walletAddress(): string {
    return this.authService.getActiveUserInstant().wallet.address;
  }

  public getBalance(): Observable<AthenaBalance> {
    return this.decentrService.athenaClient.pipe(
      switchMap((athenaClient) => athenaClient.balance.getBalance({ userWallet: this.walletAddress })),
    );
  }

  public topUpBalance(): void {
    this.router.navigate(['/', AppRoute.Portal, PortalRoute.Assets, PortalRoute.Transfer], {
      queryParams: {
        [RECEIVER_WALLET_PARAM]: 'decentr1h02d8rssedz4grxsq3s384x8tne9386adfzx07',
        [IS_AI_PARAM]: IS_AI_PARAM,
      },
    });
  }

  public getQueries(params: AskListQueryParams): Observable<QueryItem[]> {
   return this.decentrService.athenaClient.pipe(
      switchMap((athenaClient) => athenaClient.ask.getQueries(params)),
    );
  }

  public ask(askBody: Ask): Observable<any> {
    return  this.decentrService.athenaClient.pipe(
      switchMap((athenaClient) => athenaClient.ask.ask(askBody)),
    );
  }

  public markAsPaid(id: string) {
    return this.decentrService.athenaClient.pipe(
      switchMap((athenaClient) => athenaClient.ask.markAsPaid(id)
        .catch(() => this.notificationService.error(new TranslatedError('Insufficient funds. Top up your balance!')))),
    );
  }

}
