import {ChangeDetectionStrategy, ChangeDetectorRef, Component, NgZone, OnInit} from '@angular/core';
import { ControlsOf, FormBuilder, FormGroup } from '@ngneat/reactive-forms';
import {BehaviorSubject, forkJoin, from, merge, Observable, Subject} from 'rxjs';
import { startWith, switchMap, tap } from 'rxjs/operators';
import { SvgIconRegistry } from '@ngneat/svg-icon';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import {AthenaBalance, Coin, Wallet} from 'decentr-js';

import { svgReload } from '@shared/svg-icons/reload';
import { svgTopup } from '@shared/svg-icons/topup';
import { isOpenedInTab } from '@shared/utils/browser';
import { detectOs } from '@shared/utils/os';
import { InfiniteLoadingPresenter } from '@shared/utils/infinite-loading';
import { SentinelExtendedSubscription, SentinelNodeExtendedDetails } from './vpn-page.definitions';
import { VpnListFilter, VpnPageService } from './vpn-page.service';
import {svgWallet} from "@shared/svg-icons/wallet";
import {NetworkResolverService, NetworkService, SwapDestinationNetwork} from '@core/services/networks';
import {MatSnackBar} from '@angular/material/snack-bar';
import {MetaMaskInpageProvider} from "@metamask/providers";
import createMetaMaskProvider from "metamask-extension-provider";
import Eth from '@metamask/ethjs';
import {AuthService} from "@core/auth";
import {Router} from "@angular/router";


@UntilDestroy()
@Component({
  selector: 'app-vpn-page',
  templateUrl: './vpn-page.component.html',
  styleUrls: ['./vpn-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    VpnPageService,
  ],
})
export class VpnPageComponent extends InfiniteLoadingPresenter<SentinelNodeExtendedDetails> implements OnInit {
  public detectOs = detectOs();

  public isOpenedInTab = isOpenedInTab();

  public filterForm: FormGroup<ControlsOf<VpnListFilter>>;

  public balance$: BehaviorSubject<AthenaBalance> = new BehaviorSubject(undefined);

  public isConnectedToWireguard: boolean;

  public isVpnMaintenance: boolean;

  public isWgInstalled: boolean;

  public walletAddress: string = '';

  public nodes: SentinelNodeExtendedDetails[];

  public sentinelBalance: Observable<Coin>;

  private refreshBalance$: Subject<void> = new Subject();

  private refreshAll$: Subject<void> = new Subject();

  public decentrWalletAddress: Wallet['address'] = '';

  public activeUser;

  constructor(
    private changeDetectorRef: ChangeDetectorRef,
    private formBuilder: FormBuilder,
    private svgIconRegistry: SvgIconRegistry,
    private vpnPageService: VpnPageService,
    private networkResolverService: NetworkResolverService,
    private snackBar: MatSnackBar,
    private ngZone: NgZone,
    private authService: AuthService,
    private router: Router,
  ) {
    super(vpnPageService);
  }

  public ngOnInit(): void {
    console.log('init')
    this.svgIconRegistry.register([
      svgReload,
      svgTopup,
      svgWallet,
    ]);
    this.activeUser = this.authService.getActiveUserInstant();
    if (this.activeUser) {
      this.decentrWalletAddress = this.activeUser.wallet.address;
    }
    this.walletAddress = this.vpnPageService.getSentinelWalletAddress();
    this.sentinelBalance = this.vpnPageService.getSentinelBalance();
    this.filterForm = this.formBuilder.group(this.vpnPageService.filter.value);

    this.vpnPageService.checkWireguardConnection().pipe(
      untilDestroyed(this),
    ).subscribe((status) => {
      this.isConnectedToWireguard = status;
      console.log('isConnectedToWireguard:', status)

      this.changeDetectorRef.markForCheck();
    });

    forkJoin([
      this.vpnPageService.getVpnMaintenance(),
      this.vpnPageService.isWgInstalled(),
    ]).pipe(
      untilDestroyed(this),
    ).subscribe(([isVpnMaintenance, isWgInstalled]) => {
      this.isVpnMaintenance = isVpnMaintenance;
      this.isWgInstalled = isWgInstalled;

      console.log('isWgInstalled: ', isWgInstalled);
      console.log('isVpnMaintenance: ', isVpnMaintenance)

      if (!isVpnMaintenance && isWgInstalled) {
        this.initVpnPage();
      }

      this.changeDetectorRef.markForCheck();
    });
  }

  public resolveService() {
    return this.networkResolverService.resolve(SwapDestinationNetwork.ETH);
  }

  // public connectWallet(networkService: NetworkService) {
  //   const provider = createMetaMaskProvider();
  //   console.log(provider);
  //   const web3 = new Eth(provider);
  //
  //   console.log(web3.net_version());
  //
  //   // return networkService.connect().catch((error) => {
  //   //   this.ngZone.run(() => {
  //   //     this.snackBar.open(error.message, 'Ok');
  //   //   });
  //   //
  //   //   return false;
  //   // });
  // }

  public async connectWallet() {
    window.open('https://swapfortest.mainnet.decentr.xyz/');
  }

  private initVpnPage(): void {
    this.vpnPageService.init();

    merge(
      this.refreshAll$,
      this.refreshBalance$,
    ).pipe(
      startWith(void 0),
      tap(() => this.balance$.next(undefined)),
      switchMap(() => this.vpnPageService.getBalance()),
      untilDestroyed(this),
    ).subscribe((balance) => {
      this.balance$.next(balance);
    });

    this.filterForm.value$.pipe(
      untilDestroyed(this),
    ).subscribe(this.vpnPageService.filter);

    this.list$.pipe(
      untilDestroyed(this),
    ).subscribe((nodes) => {
      this.nodes = nodes;
      this.changeDetectorRef.markForCheck();
    });

    this.refreshAll$.pipe(
      untilDestroyed(this),
    ).subscribe(() => {
      this.vpnPageService.reload();
    });
  }

  public subscribeToPlan(planSubscription): void {
    this.vpnPageService.subscribeToPlan(planSubscription).pipe(
      untilDestroyed(this),
    ).subscribe(() => {
      this.refreshBalance$.next();
      this.refreshAll$.next();
    });
  }


  public cancelSubscription(subscription: any): void {
    this.vpnPageService.cancelSubscription(subscription.base.id).pipe(
      untilDestroyed(this),
    ).subscribe(() => {
      this.refreshBalance$.next();
    });
  }

  public connect(node): void {
    this.vpnPageService.connect(node, node.subscriptions[0]).pipe(
      untilDestroyed(this),
    ).subscribe(() => {
      this.refreshBalance$.next();
    });
  }

  public disconnect(node?): void {
    const sessionIds = node?.subscriptions[0]?.sessions.map(({ id }) => id) || [];
    this.vpnPageService.disconnect(sessionIds).pipe(
      untilDestroyed(this),
    ).subscribe(() => {
      this.refreshBalance$.next();
    });
  }

  public onInstallWg(): void {
    this.vpnPageService.wgInstall();
  }

  public topUpBalance(): void {
    this.vpnPageService.topUpBalance();
  }

  public refreshAll(): void {
    return this.refreshAll$.next();
  }

  public onWalletAddressCopied(): void {
    this.vpnPageService.onWalletAddressCopied();
  }
}
