import { Injectable } from '@angular/core';
import { DecentrService } from '@core/services';
import { Observable } from 'rxjs';
import {
  switchMap,
  tap,
} from 'rxjs/operators';
import { LoanItem } from 'decentr-js';
import { InfiniteLoadingService } from '@shared/utils/infinite-loading';

@Injectable()
export class LoanListService extends InfiniteLoadingService<LoanItem> {
  private readonly loadingCount: number = 20;

  constructor(
    private decentrService: DecentrService,
  ) {
    super();
  }

  protected getNextItems(): Observable<LoanItem[]> {
    const lastItem = this.list.value.length - 1;
    const paginationOptions: object = {
      take: 50,
      skip: lastItem,
    };

    return this.getLoans(paginationOptions).pipe(
      tap((pdvList) => pdvList.length < this.loadingCount && this.canLoadMore.next(false)),
    );
  }

  public getLoans(paginationOptions?): Observable<LoanItem[]> {
    return this.decentrService.vulcanClient.pipe(
      switchMap((vulcanClient) => vulcanClient.loan.getLoans(paginationOptions)),
    );
  }
}
