import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  ViewChild,
  ElementRef, AfterViewChecked, ViewChildren, QueryList, AfterViewInit, AfterContentInit
} from '@angular/core';
import {BehaviorSubject, Observable, Subject} from 'rxjs';
import { switchMap } from 'rxjs/operators';
import { AuthService } from '@core/auth';
import { UserService } from '@core/services';
import { Profile } from 'decentr-js';
import {FormControl} from "@angular/forms";
interface Message {
  content: string;
  sender: string;
  timestamp: Date;
  paid: boolean;
  id: string;
}
@Component({
  selector: 'app-chat',
  templateUrl: './chat.component.html',
  styleUrls: ['./chat.component.scss'],
  changeDetection: ChangeDetectionStrategy.Default,
})

export class ChatComponent implements OnInit, AfterViewChecked {
  @ViewChild('messagesContainer') private myScrollContainer: ElementRef;

  @Input() messages: BehaviorSubject<Message[]>;
  @Input() isSending: BehaviorSubject<boolean>;

  @Output() addMessage = new EventEmitter();
  @Output() markAsPaid = new EventEmitter();
  @Output() loadMore = new EventEmitter();

  public userInput = new FormControl();

  public profile$: Observable<Profile>;

  public skip = 5;

  public isScrolledDown = false;

  constructor(
    private authService: AuthService,
    private userService: UserService,
  ) {
  }

  ngOnInit() {
    this.profile$ = this.authService.getActiveUserAddress().pipe(
      switchMap((walletAddress) => this.userService.getProfile(walletAddress)),
    );
  }

  ngAfterViewChecked() {
    if (!this.isScrolledDown) {
      this.scrollToBottom();
    }
  }

  scrollToBottom(): void {
    if (!this.isScrolledDown) {
      this.myScrollContainer.nativeElement.scrollTop = this.myScrollContainer?.nativeElement?.scrollHeight;
    }
  }


  scrolledUp(e) {
    this.skip += 10;
    this.loadMore.emit(this.skip);
    this.isScrolledDown = true;
  }

  ask(content: string, isUser: string) {
    this.addMessage.emit({ content, isUser });
    this.scrollToBottom();
    this.isScrolledDown = false;
  }

  seeFullAnswer(id: string) {
    this.markAsPaid.emit(id);
  }

  handleUserInput() {
    if (this.userInput.value.trim()) {
      this.ask(this.userInput.value, 'User');
      this.userInput.setValue('');
    }
  }
}
