import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  TrackByFunction,
  ContentChild,
  TemplateRef, Output, EventEmitter,
} from '@angular/core';
import { SvgIconRegistry } from '@ngneat/svg-icon';

import { flagsIcons } from '@shared/svg-icons/flags';
import { NodeAccordionContentDirective } from './node-accordion-content.directive';
import { SentinelNodeExtendedDetails } from '../../pages/vpn-page/vpn-page.definitions';
import {Sessions} from "webextension-polyfill";

@Component({
  selector: 'app-node-accordion',
  templateUrl: './node-accordion.component.html',
  styleUrls: ['./node-accordion.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class NodeAccordionComponent implements OnInit {
  @Input() public nodes: SentinelNodeExtendedDetails[];

  @Input() public isConnectedToWireguard: boolean;

  @Output() public connect: EventEmitter<void> = new EventEmitter();

  @Output() public disconnect: EventEmitter<void> = new EventEmitter();

  @ContentChild(NodeAccordionContentDirective, { read: TemplateRef })
  public contentTemplateRef: TemplateRef<{ node: any }>;

  public trackByNodeAddress: TrackByFunction<SentinelNodeExtendedDetails> = ({}, { address }) => address;

  constructor(
    private svgIconRegistry: SvgIconRegistry,
  ) { }

  public ngOnInit(): void {
    this.svgIconRegistry.register([
      ...flagsIcons,
    ]);
  }

  public onDisconnect(node): void {
    this.disconnect.emit(node);
  }

  public onConnect(node): void {
    this.connect.emit(node);
  }

  public hasActiveSession(sessions): boolean {
    return sessions.some((session) => session.status === 1)
  }

  public isCanConnect(node): boolean {
    return node.subscriptions.some(subscription => subscription.base.status === 1);
  }
}
