import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  TrackByFunction,
} from '@angular/core';
import { Sort } from '@angular/material/sort';
import { Router } from '@angular/router';
import { PortalRoute } from '../../../../portal-route';
import { LoanItem } from 'decentr-js';

@Component({
  selector: 'app-loan-list-table',
  templateUrl: './loan-list-table.component.html',
  styleUrls: ['./loan-list-table.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LoanListTableComponent  {
  @Input() data: LoanItem[];

  @Output() sortClick: EventEmitter<Sort> = new EventEmitter();

  constructor(
    private router: Router,
  ) { }

  public trackById: TrackByFunction<any> = ({}, { id }) => id;



  public toTransfer(data) {
    this.router.navigate(['portal/assets/', PortalRoute.Transfer], {
      queryParams:{
        to: data.walletAddress,
        comment: 'dLoan',
        loan: true,
      },
    });
  }

}
